package com.f106.DIO.moderation.config;
import com.f106.DIO.moderation.service.ReportRetentionCleanup;import org.slf4j.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.context.annotation.Configuration;import org.springframework.scheduling.annotation.*;
/** 30일이 지난 처리 완료 신고를 정리한다. 메일 발송 재시도와는 독립된 배치다. */
@Configuration(proxyBeanMethods=false) @EnableScheduling @ConditionalOnProperty(name="dio.moderation.report-retention.enabled",havingValue="true",matchIfMissing=true)
public class ReportRetentionSchedule {private static final Logger log=LoggerFactory.getLogger(ReportRetentionSchedule.class);private final ReportRetentionCleanup cleanup;public ReportRetentionSchedule(ReportRetentionCleanup cleanup){this.cleanup=cleanup;}@Scheduled(fixedDelayString="${dio.moderation.report-retention.delay-ms:3600000}",initialDelayString="${dio.moderation.report-retention.initial-delay-ms:900000}") public void run(){try{var result=cleanup.run();if(result.reportsDeleted()>0||result.evidenceFilesDeleted()>0)log.info("Report retention cleanup: reportsDeleted={}, evidenceFilesDeleted={}",result.reportsDeleted(),result.evidenceFilesDeleted());}catch(RuntimeException error){log.error("Report retention cleanup failed: errorType={}",error.getClass().getSimpleName());}}}
